    "scraps": [
      "나는 실험에 의하여 적어도 다음과 같은 것을 배웠다. 즉 사람이 자기 꿈의 방향으로 자신있게 나아가며, 자기가 그리던 바의 생활을 하려고 노력한다면 그는 보통 때는 생각지도 못한 성공을 맞게 되리라는 것을 말이다.",
      "이처럼 삶의 가치가 가장 떨어지는 시기에 미심쩍은 자유를 누리기 위하여 인생의 황금 시절을 돈 버는 일로 보내는 사람들을 보면, 고국에 돌아와 시인 생활을 하기 위하여 먼저 인도로 건너가서 돈을 벌려고 했던 어떤 영국 사람이 생각난다. 그는 당장 다락방에 올라가 시를 쓰기 시작했어야 했다.",
      "어떠한 관찰 방법과 훈련도 항상 주의 깊게 살피는 자세를 대신해주지는 못한다. 당신은 단순한 독자나 학생이 되겠는가, 아니면 '제대로 보는 사람'이 되겠는가? 당신 앞에 놓인 것들을 보고 당신의 운명을 읽으라. 그리고 미래를 향하여 발을 내디뎌라.",
      "공중은 눈에 보이지 않는 화살로 가득 차있다. 당신 자신의 길을 빼놓고는 모두 운명의 길이다. 그러므로 당신 자신의 길에서 벗어나지 않도록 하라.",
      "그대의 눈을 안으로 돌려보라, 그러면 그대의 마음속에 여태껏 발견 못 하던 천 개의 지역을 찾아내리라. 그곳을 답사하라. 그리고 자기 자신이라는 우주학의 전문가가 되라."
    ],
